package org.bukkit.event.entity; import org.bukkit.entity.Entity; import org.bukkit.event.Cancellable; import org.bukkit.event.HandlerList; public class EntityMountEvent extends EntityEvent implements Cancellable { private final Entity vehicle; private boolean cancelled; private static final HandlerList HANDLERS=new HandlerList(); public EntityMountEvent(Entity entity,Entity vehicle){super(entity);this.vehicle=vehicle;} public Entity getVehicle(){return vehicle;} public Entity getMount(){return vehicle;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} public HandlerList getHandlers(){return HANDLERS;} public static HandlerList getHandlerList(){return HANDLERS;} }
